const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const madresDios = ee.Geometry.Polygon([
    [-72.5, -10.0],
    [-68.0, -10.0],
    [-68.0, -13.5],
    [-72.5, -13.5],
    [-72.5, -10.0]
  ]);

  const start2013 = '2013-01-01';
  const end2013 = '2013-12-31';
  const start2018 = '2018-01-01';
  const end2018 = '2018-12-31';

  // 2. Data Acquisition - Landsat 8 Surface Reflectance
  function maskL8sr(image) {
    const cloudShadowBitMask = 1 << 3;
    const cloudsBitMask = 1 << 5;
    const qa = image.select('QA_PIXEL');
    const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                 .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
    return image.updateMask(mask);
  }

  function getNDVI(image) {
    return image.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI');
  }

  // Get collections for both years
  const col2013 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterDate(start2013, end2013)
    .filterBounds(madresDios)
    .map(maskL8sr)
    .map(getNDVI);

  const col2018 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterDate(start2018, end2018)
    .filterBounds(madresDios)
    .map(maskL8sr)
    .map(getNDVI);

  // Check collection sizes
  const size2013 = col2013.size().getInfo();
  const size2018 = col2018.size().getInfo();

  print(`2013 Images: ${size2013}, 2018 Images: ${size2018}`);

  if (size2013 === 0 || size2018 === 0) {
    print("<answer>C1</answer>");
    return;
  }

  // Create median composites and calculate mean NDVI
  const composite2013 = col2013.median();
  const composite2018 = col2018.median();

  // Calculate mean NDVI with pixel count check
  const stats2013 = composite2013.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: madresDios,
    scale: 1000,
    maxPixels: 1e9
  });

  const stats2018 = composite2018.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: madresDios,
    scale: 1000,
    maxPixels: 1e9
  });

  const ndvi2013 = stats2013.get('NDVI').getInfo();
  const count2013 = stats2013.get('NDVI_count').getInfo();
  const ndvi2018 = stats2018.get('NDVI').getInfo();
  const count2018 = stats2018.get('NDVI_count').getInfo();

  print(`2013 NDVI: ${ndvi2013?.toFixed(3)}, Pixels: ${count2013}`);
  print(`2018 NDVI: ${ndvi2018?.toFixed(3)}, Pixels: ${count2018}`);

  // Check for valid pixels
  if (count2013 === 0 || count2018 === 0) {
    print("<answer>C2</answer>");
    return;
  }

  // Check for calculation failures
  if (ndvi2013 === null || ndvi2018 === null || 
      isNaN(ndvi2013) || isNaN(ndvi2018) ||
      ndvi2013 > 1 || ndvi2018 > 1 || 
      ndvi2013 < -1 || ndvi2018 < -1) {
    print("<answer>C3</answer>");
    return;
  }

  // Final comparison - forest cover decreased if 2018 NDVI < 2013 NDVI
  if (ndvi2018 < ndvi2013) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
